package com.atom.chat.settings.contract;

import com.atom.chat.AtomChat;
import com.atom.lib.frontend.contract.ContractCodec;
import com.atom.lib.frontend.contract.ContractCompatibilityException;
import com.atom.lib.frontend.contract.ContractRegistry;
import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.Set;
import java.util.concurrent.atomic.AtomicBoolean;

/** Runtime admission generated by the configured build's approved-contract check. */
public final class SettingsContractResources {
    private static final String BASE = "/META-INF/atomlib/frontend/atomchat-settings/3/";
    private static final AtomicBoolean WARNED = new AtomicBoolean();

    record Admission(ContractRegistry registry, ContractCompatibilityException incompatibility) { }

    private SettingsContractResources() {}

    public static ContractRegistry approved() {
        return Packaged.ADMISSION.registry();
    }

    /** The first real screen can explain the fallback through its normal feedback surface. */
    public static boolean takeCompatibilityWarning() {
        return Packaged.ADMISSION.incompatibility() != null && WARNED.compareAndSet(false, true);
    }

    private static final class Packaged {
        private static final Admission ADMISSION = read();
    }

    private static Admission read() {
        try (var design = SettingsContractResources.class.getResourceAsStream(BASE + "design.fcl");
             var manifest = SettingsContractResources.class.getResourceAsStream(BASE + "manifest.fcl")) {
            Admission admission = admit(design, manifest);
            if (admission.incompatibility() != null) {
                AtomChat.LOGGER.warn("Using ordinary AtomChat settings because the settings contract could not be loaded: {}",
                        admission.incompatibility().getMessage());
            }
            return admission;
        } catch (IOException e) {
            throw new UncheckedIOException("Cannot read AtomChat settings runtime admission", e);
        }
    }

    static Admission admit(InputStream design, InputStream manifest) throws IOException {
        if (design == null && manifest == null) return new Admission(null, null);
        if (design == null || manifest == null) {
            throw new IllegalStateException("Incomplete AtomChat settings runtime admission");
        }
        byte[] designBytes = design.readAllBytes();
        try {
            ContractRegistry registry = ContractRegistry.load(designBytes, manifest.readAllBytes(), Set.of("atomchat-settings/1"));
            requireIdentity(registry.namespace(), registry.version());
            return new Admission(registry, null);
        } catch (ContractCompatibilityException mismatch) {
            if (mismatch.reason() != ContractCompatibilityException.Reason.UNSUPPORTED_PROFILE
                    && mismatch.reason() != ContractCompatibilityException.Reason.MECHANISM_MISMATCH) throw mismatch;
            var rejected = ContractCodec.decode(designBytes);
            requireIdentity(rejected.namespace(), rejected.version());
            return new Admission(null, mismatch);
        }
    }

    private static void requireIdentity(String namespace, String version) {
        if (!namespace.equals("atomchat-settings") || !version.equals("3")) {
            throw new IllegalStateException("Unexpected AtomChat settings contract identity");
        }
    }
}
